-- ================================================================
-- Lebenswerk – Seed v2: 3 Demo-Trauerbücher fuer fpiepenstock NEU
-- Ausführen in: Supabase Dashboard → SQL Editor → New query → Run
-- Voraussetzung: supabase/users.sql wurde bereits ausgeführt.
--
-- Loescht die 3 bestehenden Demo-Buecher (Beitraege per ON DELETE CASCADE)
-- und legt sie NEU an: je 15 Beitragende, je 10 Fragen/Antworten (3 Saetze).
-- Bestattung = heute + 1 Monat. Idempotent (ON CONFLICT … DO UPDATE).
-- Hinweis: evtl. bereits generierte Buchbilder im Storage-Bucket
-- memorial-images/<CODE>/ bleiben als verwaiste Dateien zurueck.
-- ================================================================

begin;

-- Benutzer sicherstellen (vorhandenes Passwort NICHT ueberschreiben).
insert into app_users (username, pw_hash, pw_salt, allowed_categories, is_admin)
values ('fpiepenstock',
        '8e54496bc68e08da4f680c51d0745c2032ecad8e6b8715b8ce1a9f0f3619c74a41e3a7b905edaf0ed325d6b656c577791828c6941104178a5f05271794089d8e',
        '3f9690e698fd4f9f499a851151d14bb4', '{memorial}', false)
on conflict (username) do nothing;

-- Bestehende Demo-Buecher entfernen (Cascade loescht deren Beitraege).
delete from memorials where id in ('MARGAR', 'BAUER2', 'WAGNER');

-- ══ Buch: Margarete Hoffmann (MARGAR) — 15 Beitragende ══
insert into memorials
  (id, name, birth_year, death_year, organizer, gender, product_category, languages, funeral_date, owner_user)
values
  ('MARGAR', 'Margarete Hoffmann', '1936', '2025', 'Familie Hoffmann', 'weiblich',
   'memorial', '{de}', (current_date + interval '1 month')::date,
   (select id from app_users where username = 'fpiepenstock'))
on conflict (id) do update set
  name = excluded.name, birth_year = excluded.birth_year, death_year = excluded.death_year,
  organizer = excluded.organizer, gender = excluded.gender,
  product_category = excluded.product_category, languages = excluded.languages,
  funeral_date = excluded.funeral_date, owner_user = excluded.owner_user;

-- Thomas Hoffmann (Sohn)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAAAA', 'MARGAR', 'Thomas Hoffmann', 'Sohn', 'männlich', '[{"role":"assistant","content":"Wie würden Sie Ihre Beziehung zu Margarete als Sohn beschreiben?"},{"role":"user","content":"Als Sohn stand ich Margarete mein Leben lang besonders nahe. Wir haben unzählige Stunden miteinander verbracht und vieles gemeinsam durchlebt. Diese enge Verbindung hat mich zu dem Menschen gemacht, der ich heute bin."},{"role":"assistant","content":"Gibt es eine Erinnerung an Margarete, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Eine Erinnerung ist mir besonders geblieben. Ich erinnere mich, wie meine Mutter jeden Sonntag Apfelkuchen backte und das ganze Haus nach Zimt duftete. Dieser Augenblick bedeutet mir bis heute sehr viel."},{"role":"assistant","content":"Welche Eigenschaften haben Margarete als Menschen besonders ausgemacht?"},{"role":"user","content":"Was Margarete als Mensch ausgemacht hat, lässt sich kaum in Worte fassen. Margarete war der ruhende Pol unserer Familie und hatte für jeden ein offenes Ohr. Genau das werde ich an Margarete immer in Erinnerung behalten."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Margarete unternommen?"},{"role":"user","content":"Mit Margarete ließ sich aus dem einfachsten Anlass ein schöner Tag machen. Ob bei einem Kaffee oder einem kleinen Ausflug, die Zeit verging immer wie im Flug. Daran erinnere ich mich besonders gern."},{"role":"assistant","content":"Wie hat Margarete Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"Margarete hat mich durch manche dunkle Stunde getragen. Mit Ruhe und Zuversicht wurde aus jedem Problem etwas Lösbares. Dafür bin ich für immer dankbar."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Margarete war?"},{"role":"user","content":"An eine Sache erinnern wir uns immer wieder mit einem Lächeln. Margarete brachte uns mit einer beiläufigen Bemerkung zum Lachen, ganz ohne Absicht. Genau das machte Margarete so liebenswert."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Margarete tragen Sie bis heute weiter?"},{"role":"user","content":"Von Margarete habe ich fürs Leben viel mitgenommen. Meine Mutter lehrte mich, dass man mit Ehrlichkeit am weitesten kommt und niemanden im Stich lässt. An diesen Leitsatz halte ich mich bis heute."},{"role":"assistant","content":"Wofür hat Margarete im Leben besonders gebrannt?"},{"role":"user","content":"Die Gartenarbeit war für Margarete weit mehr als nur ein Zeitvertreib. Mit viel Liebe zum Detail war Margarete stets bei der Sache. Daran denke ich besonders gern zurück."},{"role":"assistant","content":"Was werden Sie an Margarete am meisten vermissen?"},{"role":"user","content":"Ich vermisse die Gespräche mit Margarete mehr, als Worte sagen können. Es gab immer ein offenes Ohr und einen guten Rat. Diese Nähe wird mir für immer fehlen."},{"role":"assistant","content":"Was möchten Sie Margarete zum Abschied sagen?"},{"role":"user","content":"Liebe Margarete, der Abschied von dir fällt unendlich schwer. Was du mir gegeben hast, nehme ich für mein ganzes Leben mit. Bis wir uns eines Tages wiedersehen."}]'::jsonb)
on conflict (id) do update set
  memorial_id = excluded.memorial_id, contributor_name = excluded.contributor_name,
  relationship = excluded.relationship, contributor_gender = excluded.contributor_gender,
  messages = excluded.messages;

-- Sabine Krüger (Tochter)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAAAB', 'MARGAR', 'Sabine Krüger', 'Tochter', 'weiblich', '[{"role":"assistant","content":"Wie würden Sie Ihre Beziehung zu Margarete als Tochter beschreiben?"},{"role":"user","content":"Margarete war für mich weit mehr als nur Familie. Als Tochter habe ich früh gelernt, wie viel Halt eine solche Beziehung geben kann. Auf Margarete war einfach immer Verlass."},{"role":"assistant","content":"Gibt es eine Erinnerung an Margarete, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Wenn ich zurückdenke, taucht sofort ein bestimmtes Bild auf. Unsere jährlichen Ausflüge an die Ostsee, bei denen sie barfuß Muscheln sammelte, werde ich nie vergessen. Daran denke ich noch oft mit einem warmen Gefühl."},{"role":"assistant","content":"Welche Eigenschaften haben Margarete als Menschen besonders ausgemacht?"},{"role":"user","content":"Margarete hatte ein ganz besonderes Wesen. Margarete hatte ein großes Herz für alle, die es im Leben schwer hatten. Diese Eigenschaften haben alle Menschen ringsum geprägt."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Margarete unternommen?"},{"role":"user","content":"Wir haben viele Unternehmungen miteinander geteilt, große wie kleine. Margarete war dabei stets mit Herz und voller Begeisterung bei der Sache. Solche Momente bleiben unvergesslich."},{"role":"assistant","content":"Wie hat Margarete Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"Gerade in Krisen zeigte sich, was in Margarete steckte. Da war immer ein offenes Ohr und eine helfende Hand. Diese Verlässlichkeit hat mir oft Kraft gegeben."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Margarete war?"},{"role":"user","content":"Mit Margarete wurde es nie langweilig, dafür war stets gesorgt. Eine kleine Anekdote nach der anderen begleitete unsere gemeinsamen Stunden. Diese Leichtigkeit werde ich besonders vermissen."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Margarete tragen Sie bis heute weiter?"},{"role":"user","content":"Margarete hat mir Werte vermittelt, die mich bis heute tragen. Sie brachte mir bei, dass jeder Tag ein Geschenk ist, das man bewusst nutzen sollte. Dieses Vermächtnis gebe ich gern weiter."},{"role":"assistant","content":"Wofür hat Margarete im Leben besonders gebrannt?"},{"role":"user","content":"Die Leidenschaft von Margarete für das Backen war wirklich ansteckend. Mit Hingabe und Ausdauer war Margarete immer dabei. Davon konnte sich jeder eine Scheibe abschneiden."},{"role":"assistant","content":"Was werden Sie an Margarete am meisten vermissen?"},{"role":"user","content":"Das Schwerste ist, dass Margarete nun nicht mehr da ist, wenn ich Rat suche. So oft möchte ich noch zum Hörer greifen. Dieser Verlust begleitet mich jeden Tag."},{"role":"assistant","content":"Was möchten Sie Margarete zum Abschied sagen?"},{"role":"user","content":"Liebe Margarete, danke, dass ich dich kennen und schätzen durfte. Deine Wärme und dein Vorbild werden mich immer begleiten. Schlaf gut und ruhe sanft."}]'::jsonb)
on conflict (id) do update set
  memorial_id = excluded.memorial_id, contributor_name = excluded.contributor_name,
  relationship = excluded.relationship, contributor_gender = excluded.contributor_gender,
  messages = excluded.messages;

-- Wolfgang Hoffmann (Sohn)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAAAC', 'MARGAR', 'Wolfgang Hoffmann', 'Sohn', 'männlich', '[{"role":"assistant","content":"Wie würden Sie Ihre Beziehung zu Margarete als Sohn beschreiben?"},{"role":"user","content":"Unsere Beziehung war von tiefem Vertrauen geprägt. Als Sohn konnte ich mit Margarete über alles reden, im Guten wie im Schweren. Dafür bin ich unendlich dankbar."},{"role":"assistant","content":"Gibt es eine Erinnerung an Margarete, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Es gibt einen Moment, den ich nie vergessen werde. Als Junge half ich ihr stundenlang im Garten, und sie erklärte mir geduldig jede einzelne Pflanze. Solche Momente machen mich dankbar für die gemeinsame Zeit."},{"role":"assistant","content":"Welche Eigenschaften haben Margarete als Menschen besonders ausgemacht?"},{"role":"user","content":"Über den Charakter von Margarete könnte ich endlos erzählen. Meine Mutter war bescheiden und stellte die Bedürfnisse anderer stets über ihre eigenen. So bleibt mir Margarete für immer im Gedächtnis."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Margarete unternommen?"},{"role":"user","content":"Egal was wir zusammen taten, mit Margarete wurde es zu einer schönen Erinnerung. Gemeinsame Feiern und ruhige Nachmittage gehörten gleichermaßen dazu. Ich bin dankbar für jede dieser Stunden."},{"role":"assistant","content":"Wie hat Margarete Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"Auf Margarete war Verlass, wenn es darauf ankam. In schwierigen Momenten gab es Trost und Ermutigung statt leerer Worte. Das hat mir mehr bedeutet, als ich je sagen konnte."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Margarete war?"},{"role":"user","content":"Typisch Margarete war dieser ganz besondere Humor, der jede Runde auflockerte. Eine kleine Bemerkung reichte, und alle mussten lachen. Wenn ich daran denke, muss ich noch heute schmunzeln."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Margarete tragen Sie bis heute weiter?"},{"role":"user","content":"Eines hat mich besonders geprägt. Von ihr habe ich gelernt, auch in schwierigen Zeiten die Zuversicht nicht zu verlieren. Dafür bin ich für immer dankbar."},{"role":"assistant","content":"Wofür hat Margarete im Leben besonders gebrannt?"},{"role":"user","content":"Wenn es um das Singen im Kirchenchor ging, blühte Margarete regelrecht auf. Diese Begeisterung hat viele Menschen im Umfeld angesteckt. Es war schön, Margarete dabei zu erleben."},{"role":"assistant","content":"Was werden Sie an Margarete am meisten vermissen?"},{"role":"user","content":"Mir fehlt die herzliche Art von Margarete, die jeden Raum wärmer machte. Gerade die kleinen Momente des Alltags vermisse ich am meisten. Es bleibt eine große Leere."},{"role":"assistant","content":"Was möchten Sie Margarete zum Abschied sagen?"},{"role":"user","content":"Liebe Margarete, du fehlst uns mehr, als sich in Worte fassen lässt. Wir werden dich in liebevoller Erinnerung behalten und oft von dir erzählen. Mach es gut, geliebter Mensch."}]'::jsonb)
on conflict (id) do update set
  memorial_id = excluded.memorial_id, contributor_name = excluded.contributor_name,
  relationship = excluded.relationship, contributor_gender = excluded.contributor_gender,
  messages = excluded.messages;

-- Lena Hoffmann (Enkelin)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAAAD', 'MARGAR', 'Lena Hoffmann', 'Enkelin', 'weiblich', '[{"role":"assistant","content":"Wie würden Sie Ihre Beziehung zu Margarete als Enkelin beschreiben?"},{"role":"user","content":"Ich hatte das große Glück, Margarete als Enkelin so nah zu sein. Gemeinsame Feste, Sorgen und Freuden haben uns über die Jahre fest verbunden. Diese Nähe werde ich für immer in meinem Herzen tragen."},{"role":"assistant","content":"Gibt es eine Erinnerung an Margarete, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Eine Erinnerung ist mir besonders geblieben. Im Sommer pflückten wir zusammen Erdbeeren im Garten, und sie sang mir dabei alte Lieder vor. Dieser Augenblick bedeutet mir bis heute sehr viel."},{"role":"assistant","content":"Welche Eigenschaften haben Margarete als Menschen besonders ausgemacht?"},{"role":"user","content":"Was Margarete als Mensch ausgemacht hat, lässt sich kaum in Worte fassen. Für mich war Oma die beste Geschichtenerzählerin der ganzen Welt. Genau das werde ich an Margarete immer in Erinnerung behalten."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Margarete unternommen?"},{"role":"user","content":"Die gemeinsamen Unternehmungen mit Margarete habe ich immer genossen. Es war nie wichtig, was wir taten, sondern dass wir es zusammen taten. Diese Zeit war für mich ein echtes Geschenk."},{"role":"assistant","content":"Wie hat Margarete Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"In schweren Zeiten konnte ich mich immer auf Margarete verlassen. Ein gutes Wort oder einfach nur Zuhören kam stets im richtigen Moment. Diesen Rückhalt werde ich nie vergessen."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Margarete war?"},{"role":"user","content":"Es gab so viele kleine Geschichten, die einfach typisch Margarete waren. Selbst in den alltäglichsten Momenten steckte oft ein Augenzwinkern. Diese Heiterkeit fehlt mir sehr."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Margarete tragen Sie bis heute weiter?"},{"role":"user","content":"Von Margarete habe ich fürs Leben viel mitgenommen. Oma zeigte mir, dass gute Dinge Zeit brauchen und sich Geduld immer lohnt. An diesen Leitsatz halte ich mich bis heute."},{"role":"assistant","content":"Wofür hat Margarete im Leben besonders gebrannt?"},{"role":"user","content":"Margarete liebte das Stricken über alles. Man spürte sofort, wie viel Freude das bereitete. Diese Hingabe hat mich immer beeindruckt."},{"role":"assistant","content":"Was werden Sie an Margarete am meisten vermissen?"},{"role":"user","content":"Am meisten werde ich die Gegenwart von Margarete vermissen, dieses Gefühl von Geborgenheit. Schon eine kurze Begegnung konnte den ganzen Tag heller machen. Diese Lücke lässt sich nicht füllen."},{"role":"assistant","content":"Was möchten Sie Margarete zum Abschied sagen?"},{"role":"user","content":"Liebe Margarete, dein Andenken bleibt für immer lebendig. Ich bin dankbar für jeden Augenblick, den wir teilen durften. In Liebe und Dankbarkeit nehme ich Abschied."}]'::jsonb)
on conflict (id) do update set
  memorial_id = excluded.memorial_id, contributor_name = excluded.contributor_name,
  relationship = excluded.relationship, contributor_gender = excluded.contributor_gender,
  messages = excluded.messages;

-- Jonas Krüger (Enkel)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAAAE', 'MARGAR', 'Jonas Krüger', 'Enkel', 'männlich', '[{"role":"assistant","content":"Wie würden Sie Ihre Beziehung zu Margarete als Enkel beschreiben?"},{"role":"user","content":"Schon als Kind spürte ich, wie besonders meine Verbindung zu Margarete war. Als Enkel durfte ich Margarete über viele Jahre begleiten. Das habe ich nie als selbstverständlich genommen."},{"role":"assistant","content":"Gibt es eine Erinnerung an Margarete, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Wenn ich zurückdenke, taucht sofort ein bestimmtes Bild auf. Bei Oma gab es immer heiße Schokolade, während sie mir von früher erzählte. Daran denke ich noch oft mit einem warmen Gefühl."},{"role":"assistant","content":"Welche Eigenschaften haben Margarete als Menschen besonders ausgemacht?"},{"role":"user","content":"Margarete hatte ein ganz besonderes Wesen. Oma blieb bis ins hohe Alter neugierig und nahm jeden Menschen ernst. Diese Eigenschaften haben alle Menschen ringsum geprägt."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Margarete unternommen?"},{"role":"user","content":"Am liebsten haben wir gemeinsam Zeit in Ruhe verbracht, ganz ohne großes Programm. Schon ein Spaziergang oder ein langes Gespräch mit Margarete war etwas Besonderes. Diese gemeinsamen Stunden fehlen mir heute am meisten."},{"role":"assistant","content":"Wie hat Margarete Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"Wenn es mir einmal nicht gut ging, war Margarete sofort zur Stelle. Ohne viel Aufhebens wurde geholfen, ganz selbstverständlich. So einen Menschen an seiner Seite zu wissen, war ein großes Glück."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Margarete war?"},{"role":"user","content":"Margarete hatte ein Talent dafür, im richtigen Moment das Richtige zu sagen. Manche Bemerkung sorgt in der Familie bis heute für Gelächter. Solche Geschichten halten die Erinnerung lebendig."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Margarete tragen Sie bis heute weiter?"},{"role":"user","content":"Margarete hat mir Werte vermittelt, die mich bis heute tragen. Sie lehrte mich, dass man mit Freundlichkeit mehr erreicht als mit Härte. Dieses Vermächtnis gebe ich gern weiter."},{"role":"assistant","content":"Wofür hat Margarete im Leben besonders gebrannt?"},{"role":"user","content":"Für das Spazierengehen konnte Margarete sich jederzeit begeistern. Stundenlang ging Margarete darin auf und vergaß die Zeit. Das gehörte einfach zu Margarete."},{"role":"assistant","content":"Was werden Sie an Margarete am meisten vermissen?"},{"role":"user","content":"Was mir am meisten fehlt, ist die Stimme von Margarete und das vertraute Lachen. So viele kleine Gewohnheiten erinnern mich täglich daran. Der Abschied tut sehr weh."},{"role":"assistant","content":"Was möchten Sie Margarete zum Abschied sagen?"},{"role":"user","content":"Liebe Margarete, ich danke dir von Herzen für all die gemeinsamen Jahre. Du wirst für immer einen festen Platz in meinem Herzen behalten. Ruhe nun in Frieden."}]'::jsonb)
on conflict (id) do update set
  memorial_id = excluded.memorial_id, contributor_name = excluded.contributor_name,
  relationship = excluded.relationship, contributor_gender = excluded.contributor_gender,
  messages = excluded.messages;

