-- Heinrich Vogt (Nachbar)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAAAG', 'MARGAR', 'Heinrich Vogt', 'Nachbar', 'männlich', '[{"role":"assistant","content":"Wie haben Sie Margarete kennengelernt, und was hat Sie verbunden?"},{"role":"user","content":"Unsere Wege kreuzten sich vor langer Zeit, und Margarete wuchs mir schnell ans Herz. Als Nachbar habe ich Margarete über viele Jahre erlebt. Eine bessere Begegnung hätte ich mir nicht wünschen können."},{"role":"assistant","content":"Gibt es eine Erinnerung an Margarete, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Eine Erinnerung ist mir besonders geblieben. Als meine Frau krank wurde, brachte Margarete uns jeden Tag eine warme Suppe vorbei. Dieser Augenblick bedeutet mir bis heute sehr viel."},{"role":"assistant","content":"Welche Eigenschaften haben Margarete als Menschen besonders ausgemacht?"},{"role":"user","content":"Was Margarete als Mensch ausgemacht hat, lässt sich kaum in Worte fassen. Frau Hoffmann war über vierzig Jahre eine herzliche und hilfsbereite Nachbarin. Genau das werde ich an Margarete immer in Erinnerung behalten."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Margarete unternommen?"},{"role":"user","content":"Wir haben viele Unternehmungen miteinander geteilt, große wie kleine. Margarete war dabei stets mit Herz und voller Begeisterung bei der Sache. Solche Momente bleiben unvergesslich."},{"role":"assistant","content":"Wie hat Margarete Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"Gerade in Krisen zeigte sich, was in Margarete steckte. Da war immer ein offenes Ohr und eine helfende Hand. Diese Verlässlichkeit hat mir oft Kraft gegeben."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Margarete war?"},{"role":"user","content":"Mit Margarete wurde es nie langweilig, dafür war stets gesorgt. Eine kleine Anekdote nach der anderen begleitete unsere gemeinsamen Stunden. Diese Leichtigkeit werde ich besonders vermissen."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Margarete tragen Sie bis heute weiter?"},{"role":"user","content":"Von Margarete habe ich fürs Leben viel mitgenommen. Sie zeigte mir, was gute Nachbarschaft wirklich bedeutet. An diesen Leitsatz halte ich mich bis heute."},{"role":"assistant","content":"Wofür hat Margarete im Leben besonders gebrannt?"},{"role":"user","content":"Die Leidenschaft von Margarete für das Backen war wirklich ansteckend. Mit Hingabe und Ausdauer war Margarete immer dabei. Davon konnte sich jeder eine Scheibe abschneiden."},{"role":"assistant","content":"Was werden Sie an Margarete am meisten vermissen?"},{"role":"user","content":"Das Schwerste ist, dass Margarete nun nicht mehr da ist, wenn ich Rat suche. So oft möchte ich noch zum Hörer greifen. Dieser Verlust begleitet mich jeden Tag."},{"role":"assistant","content":"Was möchten Sie Margarete zum Abschied sagen?"},{"role":"user","content":"Liebe Margarete, danke, dass ich dich kennen und schätzen durfte. Deine Wärme und dein Vorbild werden mich immer begleiten. Schlaf gut und ruhe sanft."}]'::jsonb)
