-- Ruth Lindemann (beste Freundin)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAAAH', 'MARGAR', 'Ruth Lindemann', 'beste Freundin', 'weiblich', '[{"role":"assistant","content":"Wie haben Sie Margarete kennengelernt, und was hat Sie verbunden?"},{"role":"user","content":"Ich lernte Margarete als beste Freundin kennen und schätzen. Vom ersten Moment an verstanden wir uns ohne viele Worte. Daraus erwuchs eine Verbindung, die mir bis heute viel bedeutet."},{"role":"assistant","content":"Gibt es eine Erinnerung an Margarete, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Wenn ich zurückdenke, taucht sofort ein bestimmtes Bild auf. Über sechzig Jahre trafen wir uns jeden Donnerstag zum Kaffee und teilten einfach alles. Daran denke ich noch oft mit einem warmen Gefühl."},{"role":"assistant","content":"Welche Eigenschaften haben Margarete als Menschen besonders ausgemacht?"},{"role":"user","content":"Margarete hatte ein ganz besonderes Wesen. Margarete war eine absolut treue Freundin, die nie ein Geheimnis verriet. Diese Eigenschaften haben alle Menschen ringsum geprägt."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Margarete unternommen?"},{"role":"user","content":"Egal was wir zusammen taten, mit Margarete wurde es zu einer schönen Erinnerung. Gemeinsame Feiern und ruhige Nachmittage gehörten gleichermaßen dazu. Ich bin dankbar für jede dieser Stunden."},{"role":"assistant","content":"Wie hat Margarete Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"Auf Margarete war Verlass, wenn es darauf ankam. In schwierigen Momenten gab es Trost und Ermutigung statt leerer Worte. Das hat mir mehr bedeutet, als ich je sagen konnte."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Margarete war?"},{"role":"user","content":"Typisch Margarete war dieser ganz besondere Humor, der jede Runde auflockerte. Eine kleine Bemerkung reichte, und alle mussten lachen. Wenn ich daran denke, muss ich noch heute schmunzeln."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Margarete tragen Sie bis heute weiter?"},{"role":"user","content":"Margarete hat mir Werte vermittelt, die mich bis heute tragen. Von ihr lernte ich, dass wahre Freundschaft jede Entfernung überdauert. Dieses Vermächtnis gebe ich gern weiter."},{"role":"assistant","content":"Wofür hat Margarete im Leben besonders gebrannt?"},{"role":"user","content":"Wenn es um das Singen im Kirchenchor ging, blühte Margarete regelrecht auf. Diese Begeisterung hat viele Menschen im Umfeld angesteckt. Es war schön, Margarete dabei zu erleben."},{"role":"assistant","content":"Was werden Sie an Margarete am meisten vermissen?"},{"role":"user","content":"Mir fehlt die herzliche Art von Margarete, die jeden Raum wärmer machte. Gerade die kleinen Momente des Alltags vermisse ich am meisten. Es bleibt eine große Leere."},{"role":"assistant","content":"Was möchten Sie Margarete zum Abschied sagen?"},{"role":"user","content":"Liebe Margarete, du fehlst uns mehr, als sich in Worte fassen lässt. Wir werden dich in liebevoller Erinnerung behalten und oft von dir erzählen. Mach es gut, geliebter Mensch."}]'::jsonb)
