insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAAAP', 'MARGAR', 'Johannes Reuter', 'Gemeindepfarrer', 'männlich', '[{"role":"assistant","content":"Wie haben Sie Margarete kennengelernt, und was hat Sie verbunden?"},{"role":"user","content":"Als Gemeindepfarrer war ich Margarete über die Jahre eng verbunden. Wir teilten Freud und Leid und konnten uns aufeinander verlassen. Solche Menschen trifft man im Leben nur selten."},{"role":"assistant","content":"Gibt es eine Erinnerung an Margarete, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Wenn ich zurückdenke, taucht sofort ein bestimmtes Bild auf. In der Gemeinde war Margarete stets zur Stelle, wenn helfende Hände gebraucht wurden. Daran denke ich noch oft mit einem warmen Gefühl."},{"role":"assistant","content":"Welche Eigenschaften haben Margarete als Menschen besonders ausgemacht?"},{"role":"user","content":"Margarete hatte ein ganz besonderes Wesen. Margarete lebte ihren Glauben durch Taten der Nächstenliebe. Diese Eigenschaften haben alle Menschen ringsum geprägt."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Margarete unternommen?"},{"role":"user","content":"Die gemeinsamen Unternehmungen mit Margarete habe ich immer genossen. Es war nie wichtig, was wir taten, sondern dass wir es zusammen taten. Diese Zeit war für mich ein echtes Geschenk."},{"role":"assistant","content":"Wie hat Margarete Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"In schweren Zeiten konnte ich mich immer auf Margarete verlassen. Ein gutes Wort oder einfach nur Zuhören kam stets im richtigen Moment. Diesen Rückhalt werde ich nie vergessen."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Margarete war?"},{"role":"user","content":"Es gab so viele kleine Geschichten, die einfach typisch Margarete waren. Selbst in den alltäglichsten Momenten steckte oft ein Augenzwinkern. Diese Heiterkeit fehlt mir sehr."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Margarete tragen Sie bis heute weiter?"},{"role":"user","content":"Margarete hat mir Werte vermittelt, die mich bis heute tragen. Ihr Beispiel lehrte mich, dass gelebter Glaube mehr zählt als viele Worte. Dieses Vermächtnis gebe ich gern weiter."},{"role":"assistant","content":"Wofür hat Margarete im Leben besonders gebrannt?"},{"role":"user","content":"Margarete liebte das Stricken über alles. Man spürte sofort, wie viel Freude das bereitete. Diese Hingabe hat mich immer beeindruckt."},{"role":"assistant","content":"Was werden Sie an Margarete am meisten vermissen?"},{"role":"user","content":"Am meisten werde ich die Gegenwart von Margarete vermissen, dieses Gefühl von Geborgenheit. Schon eine kurze Begegnung konnte den ganzen Tag heller machen. Diese Lücke lässt sich nicht füllen."},{"role":"assistant","content":"Was möchten Sie Margarete zum Abschied sagen?"},{"role":"user","content":"Liebe Margarete, dein Andenken bleibt für immer lebendig. Ich bin dankbar für jeden Augenblick, den wir teilen durften. In Liebe und Dankbarkeit nehme ich Abschied."}]'::jsonb)
on conflict (id) do update set
  memorial_id = excluded.memorial_id, contributor_name = excluded.contributor_name,
  relationship = excluded.relationship, contributor_gender = excluded.contributor_gender,
  messages = excluded.messages;

-- Hannelore Busch (Schwester)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAAAQ', 'MARGAR', 'Hannelore Busch', 'Schwester', 'weiblich', '[{"role":"assistant","content":"Wie würden Sie Ihre Beziehung zu Margarete als Schwester beschreiben?"},{"role":"user","content":"Schon als Kind spürte ich, wie besonders meine Verbindung zu Margarete war. Als Schwester durfte ich Margarete über viele Jahre begleiten. Das habe ich nie als selbstverständlich genommen."},{"role":"assistant","content":"Gibt es eine Erinnerung an Margarete, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Es gibt einen Moment, den ich nie vergessen werde. Als Kinder teilten wir uns ein Zimmer und flüsterten uns nachts unsere Geheimnisse zu. Solche Momente machen mich dankbar für die gemeinsame Zeit."},{"role":"assistant","content":"Welche Eigenschaften haben Margarete als Menschen besonders ausgemacht?"},{"role":"user","content":"Über den Charakter von Margarete könnte ich endlos erzählen. Meine Schwester war mein Leben lang mein Vorbild und mein sicherer Hafen. So bleibt mir Margarete für immer im Gedächtnis."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Margarete unternommen?"},{"role":"user","content":"Am liebsten haben wir gemeinsam Zeit in Ruhe verbracht, ganz ohne großes Programm. Schon ein Spaziergang oder ein langes Gespräch mit Margarete war etwas Besonderes. Diese gemeinsamen Stunden fehlen mir heute am meisten."},{"role":"assistant","content":"Wie hat Margarete Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"Wenn es mir einmal nicht gut ging, war Margarete sofort zur Stelle. Ohne viel Aufhebens wurde geholfen, ganz selbstverständlich. So einen Menschen an seiner Seite zu wissen, war ein großes Glück."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Margarete war?"},{"role":"user","content":"Margarete hatte ein Talent dafür, im richtigen Moment das Richtige zu sagen. Manche Bemerkung sorgt in der Familie bis heute für Gelächter. Solche Geschichten halten die Erinnerung lebendig."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Margarete tragen Sie bis heute weiter?"},{"role":"user","content":"Eines hat mich besonders geprägt. Von ihr lernte ich, dass man füreinander einsteht, ganz gleich was kommt. Dafür bin ich für immer dankbar."},{"role":"assistant","content":"Wofür hat Margarete im Leben besonders gebrannt?"},{"role":"user","content":"Für das Spazierengehen konnte Margarete sich jederzeit begeistern. Stundenlang ging Margarete darin auf und vergaß die Zeit. Das gehörte einfach zu Margarete."},{"role":"assistant","content":"Was werden Sie an Margarete am meisten vermissen?"},{"role":"user","content":"Was mir am meisten fehlt, ist die Stimme von Margarete und das vertraute Lachen. So viele kleine Gewohnheiten erinnern mich täglich daran. Der Abschied tut sehr weh."},{"role":"assistant","content":"Was möchten Sie Margarete zum Abschied sagen?"},{"role":"user","content":"Liebe Margarete, ich danke dir von Herzen für all die gemeinsamen Jahre. Du wirst für immer einen festen Platz in meinem Herzen behalten. Ruhe nun in Frieden."}]'::jsonb)
on conflict (id) do update set
  memorial_id = excluded.memorial_id, contributor_name = excluded.contributor_name,
  relationship = excluded.relationship, contributor_gender = excluded.contributor_gender,
  messages = excluded.messages;

