-- Karin Bauer (Ehefrau)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAAAR', 'BAUER2', 'Karin Bauer', 'Ehefrau', 'weiblich', '[{"role":"assistant","content":"Wie würden Sie Ihre Beziehung zu Fritz als Ehefrau beschreiben?"},{"role":"user","content":"Als Ehefrau stand ich Fritz mein Leben lang besonders nahe. Wir haben unzählige Stunden miteinander verbracht und vieles gemeinsam durchlebt. Diese enge Verbindung hat mich zu dem Menschen gemacht, der ich heute bin."},{"role":"assistant","content":"Gibt es eine Erinnerung an Fritz, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Eine Erinnerung ist mir besonders geblieben. Auf einem Sommerfest 1965 forderte Fritz mich zum Tanz auf und ließ mich nie wieder los. Dieser Augenblick bedeutet mir bis heute sehr viel."},{"role":"assistant","content":"Welche Eigenschaften haben Fritz als Menschen besonders ausgemacht?"},{"role":"user","content":"Was Fritz als Mensch ausgemacht hat, lässt sich kaum in Worte fassen. Mein Mann war herzensgut, und sein Wort galt, darauf konnte sich jeder verlassen. Genau das werde ich an Fritz immer in Erinnerung behalten."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Fritz unternommen?"},{"role":"user","content":"Mit Fritz ließ sich aus dem einfachsten Anlass ein schöner Tag machen. Ob bei einem Kaffee oder einem kleinen Ausflug, die Zeit verging immer wie im Flug. Daran erinnere ich mich besonders gern."},{"role":"assistant","content":"Wie hat Fritz Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"Fritz hat mich durch manche dunkle Stunde getragen. Mit Ruhe und Zuversicht wurde aus jedem Problem etwas Lösbares. Dafür bin ich für immer dankbar."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Fritz war?"},{"role":"user","content":"An eine Sache erinnern wir uns immer wieder mit einem Lächeln. Fritz brachte uns mit einer beiläufigen Bemerkung zum Lachen, ganz ohne Absicht. Genau das machte Fritz so liebenswert."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Fritz tragen Sie bis heute weiter?"},{"role":"user","content":"Von Fritz habe ich fürs Leben viel mitgenommen. Fritz lehrte mich, dass man jede Last gemeinsam leichter trägt. An diesen Leitsatz halte ich mich bis heute."},{"role":"assistant","content":"Wofür hat Fritz im Leben besonders gebrannt?"},{"role":"user","content":"Die Gartenarbeit war für Fritz weit mehr als nur ein Zeitvertreib. Mit viel Liebe zum Detail war Fritz stets bei der Sache. Daran denke ich besonders gern zurück."},{"role":"assistant","content":"Was werden Sie an Fritz am meisten vermissen?"},{"role":"user","content":"Ich vermisse die Gespräche mit Fritz mehr, als Worte sagen können. Es gab immer ein offenes Ohr und einen guten Rat. Diese Nähe wird mir für immer fehlen."},{"role":"assistant","content":"Was möchten Sie Fritz zum Abschied sagen?"},{"role":"user","content":"Lieber Fritz, der Abschied von dir fällt unendlich schwer. Was du mir gegeben hast, nehme ich für mein ganzes Leben mit. Bis wir uns eines Tages wiedersehen."}]'::jsonb)
on conflict (id) do update set
  memorial_id = excluded.memorial_id, contributor_name = excluded.contributor_name,
  relationship = excluded.relationship, contributor_gender = excluded.contributor_gender,
  messages = excluded.messages;

-- Michael Bauer (Sohn)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAAAS', 'BAUER2', 'Michael Bauer', 'Sohn', 'männlich', '[{"role":"assistant","content":"Wie würden Sie Ihre Beziehung zu Fritz als Sohn beschreiben?"},{"role":"user","content":"Fritz war für mich weit mehr als nur Familie. Als Sohn habe ich früh gelernt, wie viel Halt eine solche Beziehung geben kann. Auf Fritz war einfach immer Verlass."},{"role":"assistant","content":"Gibt es eine Erinnerung an Fritz, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Wenn ich zurückdenke, taucht sofort ein bestimmtes Bild auf. Stundenlang sah ich ihm in der Werkstatt zu, wie er aus Holz die schönsten Dinge schuf. Daran denke ich noch oft mit einem warmen Gefühl."},{"role":"assistant","content":"Welche Eigenschaften haben Fritz als Menschen besonders ausgemacht?"},{"role":"user","content":"Fritz hatte ein ganz besonderes Wesen. Mein Vater war ein harter Arbeiter und zugleich ein echter Familienmensch. Diese Eigenschaften haben alle Menschen ringsum geprägt."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Fritz unternommen?"},{"role":"user","content":"Wir haben viele Unternehmungen miteinander geteilt, große wie kleine. Fritz war dabei stets mit Herz und voller Begeisterung bei der Sache. Solche Momente bleiben unvergesslich."},{"role":"assistant","content":"Wie hat Fritz Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"Gerade in Krisen zeigte sich, was in Fritz steckte. Da war immer ein offenes Ohr und eine helfende Hand. Diese Verlässlichkeit hat mir oft Kraft gegeben."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Fritz war?"},{"role":"user","content":"Mit Fritz wurde es nie langweilig, dafür war stets gesorgt. Eine kleine Anekdote nach der anderen begleitete unsere gemeinsamen Stunden. Diese Leichtigkeit werde ich besonders vermissen."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Fritz tragen Sie bis heute weiter?"},{"role":"user","content":"Fritz hat mir Werte vermittelt, die mich bis heute tragen. Von ihm lernte ich, eine Aufgabe immer ordentlich zu Ende zu bringen. Dieses Vermächtnis gebe ich gern weiter."},{"role":"assistant","content":"Wofür hat Fritz im Leben besonders gebrannt?"},{"role":"user","content":"Die Leidenschaft von Fritz für das Singen im Gesangverein war wirklich ansteckend. Mit Hingabe und Ausdauer war Fritz immer dabei. Davon konnte sich jeder eine Scheibe abschneiden."},{"role":"assistant","content":"Was werden Sie an Fritz am meisten vermissen?"},{"role":"user","content":"Das Schwerste ist, dass Fritz nun nicht mehr da ist, wenn ich Rat suche. So oft möchte ich noch zum Hörer greifen. Dieser Verlust begleitet mich jeden Tag."},{"role":"assistant","content":"Was möchten Sie Fritz zum Abschied sagen?"},{"role":"user","content":"Lieber Fritz, danke, dass ich dich kennen und schätzen durfte. Deine Wärme und dein Vorbild werden mich immer begleiten. Schlaf gut und ruhe sanft."}]'::jsonb)
on conflict (id) do update set
  memorial_id = excluded.memorial_id, contributor_name = excluded.contributor_name,
  relationship = excluded.relationship, contributor_gender = excluded.contributor_gender,
  messages = excluded.messages;

-- Andreas Schmidt (Schwiegersohn)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAAAT', 'BAUER2', 'Andreas Schmidt', 'Schwiegersohn', 'männlich', '[{"role":"assistant","content":"Wie würden Sie Ihre Beziehung zu Fritz als Schwiegersohn beschreiben?"},{"role":"user","content":"Unsere Beziehung war von tiefem Vertrauen geprägt. Als Schwiegersohn konnte ich mit Fritz über alles reden, im Guten wie im Schweren. Dafür bin ich unendlich dankbar."},{"role":"assistant","content":"Gibt es eine Erinnerung an Fritz, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Es gibt einen Moment, den ich nie vergessen werde. Beim ersten Treffen nahm Fritz mir sofort die Nervosität und reichte mir herzlich die Hand. Solche Momente machen mich dankbar für die gemeinsame Zeit."},{"role":"assistant","content":"Welche Eigenschaften haben Fritz als Menschen besonders ausgemacht?"},{"role":"user","content":"Über den Charakter von Fritz könnte ich endlos erzählen. Fritz war geradlinig und sagte stets offen, was er dachte. So bleibt mir Fritz für immer im Gedächtnis."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Fritz unternommen?"},{"role":"user","content":"Egal was wir zusammen taten, mit Fritz wurde es zu einer schönen Erinnerung. Gemeinsame Feiern und ruhige Nachmittage gehörten gleichermaßen dazu. Ich bin dankbar für jede dieser Stunden."},{"role":"assistant","content":"Wie hat Fritz Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"Auf Fritz war Verlass, wenn es darauf ankam. In schwierigen Momenten gab es Trost und Ermutigung statt leerer Worte. Das hat mir mehr bedeutet, als ich je sagen konnte."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Fritz war?"},{"role":"user","content":"Typisch Fritz war dieser ganz besondere Humor, der jede Runde auflockerte. Eine kleine Bemerkung reichte, und alle mussten lachen. Wenn ich daran denke, muss ich noch heute schmunzeln."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Fritz tragen Sie bis heute weiter?"},{"role":"user","content":"Eines hat mich besonders geprägt. Er zeigte mir, dass man mit Ruhe und Geduld jedes Problem lösen kann. Dafür bin ich für immer dankbar."},{"role":"assistant","content":"Wofür hat Fritz im Leben besonders gebrannt?"},{"role":"user","content":"Wenn es um das Skatspiel ging, blühte Fritz regelrecht auf. Diese Begeisterung hat viele Menschen im Umfeld angesteckt. Es war schön, Fritz dabei zu erleben."},{"role":"assistant","content":"Was werden Sie an Fritz am meisten vermissen?"},{"role":"user","content":"Mir fehlt die herzliche Art von Fritz, die jeden Raum wärmer machte. Gerade die kleinen Momente des Alltags vermisse ich am meisten. Es bleibt eine große Leere."},{"role":"assistant","content":"Was möchten Sie Fritz zum Abschied sagen?"},{"role":"user","content":"Lieber Fritz, du fehlst uns mehr, als sich in Worte fassen lässt. Wir werden dich in liebevoller Erinnerung behalten und oft von dir erzählen. Mach es gut, geliebter Mensch."}]'::jsonb)
on conflict (id) do update set
  memorial_id = excluded.memorial_id, contributor_name = excluded.contributor_name,
  relationship = excluded.relationship, contributor_gender = excluded.contributor_gender,
  messages = excluded.messages;

-- Petra Bauer (Tochter)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAAAU', 'BAUER2', 'Petra Bauer', 'Tochter', 'weiblich', '[{"role":"assistant","content":"Wie würden Sie Ihre Beziehung zu Fritz als Tochter beschreiben?"},{"role":"user","content":"Ich hatte das große Glück, Fritz als Tochter so nah zu sein. Gemeinsame Feste, Sorgen und Freuden haben uns über die Jahre fest verbunden. Diese Nähe werde ich für immer in meinem Herzen tragen."},{"role":"assistant","content":"Gibt es eine Erinnerung an Fritz, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Eine Erinnerung ist mir besonders geblieben. Sonntags nahm er mich mit zum Angeln, und wir saßen schweigend und glücklich am Ufer. Dieser Augenblick bedeutet mir bis heute sehr viel."},{"role":"assistant","content":"Welche Eigenschaften haben Fritz als Menschen besonders ausgemacht?"},{"role":"user","content":"Was Fritz als Mensch ausgemacht hat, lässt sich kaum in Worte fassen. Mein Vater war streng, doch unter der rauen Schale verbarg sich ein weiches Herz. Genau das werde ich an Fritz immer in Erinnerung behalten."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Fritz unternommen?"},{"role":"user","content":"Die gemeinsamen Unternehmungen mit Fritz habe ich immer genossen. Es war nie wichtig, was wir taten, sondern dass wir es zusammen taten. Diese Zeit war für mich ein echtes Geschenk."},{"role":"assistant","content":"Wie hat Fritz Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"In schweren Zeiten konnte ich mich immer auf Fritz verlassen. Ein gutes Wort oder einfach nur Zuhören kam stets im richtigen Moment. Diesen Rückhalt werde ich nie vergessen."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Fritz war?"},{"role":"user","content":"Es gab so viele kleine Geschichten, die einfach typisch Fritz waren. Selbst in den alltäglichsten Momenten steckte oft ein Augenzwinkern. Diese Heiterkeit fehlt mir sehr."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Fritz tragen Sie bis heute weiter?"},{"role":"user","content":"Von Fritz habe ich fürs Leben viel mitgenommen. Von ihm habe ich gelernt, immer zu meinem Wort zu stehen. An diesen Leitsatz halte ich mich bis heute."},{"role":"assistant","content":"Wofür hat Fritz im Leben besonders gebrannt?"},{"role":"user","content":"Fritz liebte das Heimwerken über alles. Man spürte sofort, wie viel Freude das bereitete. Diese Hingabe hat mich immer beeindruckt."},{"role":"assistant","content":"Was werden Sie an Fritz am meisten vermissen?"},{"role":"user","content":"Am meisten werde ich die Gegenwart von Fritz vermissen, dieses Gefühl von Geborgenheit. Schon eine kurze Begegnung konnte den ganzen Tag heller machen. Diese Lücke lässt sich nicht füllen."},{"role":"assistant","content":"Was möchten Sie Fritz zum Abschied sagen?"},{"role":"user","content":"Lieber Fritz, dein Andenken bleibt für immer lebendig. Ich bin dankbar für jeden Augenblick, den wir teilen durften. In Liebe und Dankbarkeit nehme ich Abschied."}]'::jsonb)
