-- Laura Schmidt (Enkelin)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAAAW', 'BAUER2', 'Laura Schmidt', 'Enkelin', 'weiblich', '[{"role":"assistant","content":"Wie würden Sie Ihre Beziehung zu Fritz als Enkelin beschreiben?"},{"role":"user","content":"Als Enkelin stand ich Fritz mein Leben lang besonders nahe. Wir haben unzählige Stunden miteinander verbracht und vieles gemeinsam durchlebt. Diese enge Verbindung hat mich zu dem Menschen gemacht, der ich heute bin."},{"role":"assistant","content":"Gibt es eine Erinnerung an Fritz, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Es gibt einen Moment, den ich nie vergessen werde. In seiner Werkstatt baute er mir ein Puppenhaus, an dem wir wochenlang gemeinsam werkelten. Solche Momente machen mich dankbar für die gemeinsame Zeit."},{"role":"assistant","content":"Welche Eigenschaften haben Fritz als Menschen besonders ausgemacht?"},{"role":"user","content":"Über den Charakter von Fritz könnte ich endlos erzählen. Opa war geduldig und erklärte mir alles so oft, bis ich es verstand. So bleibt mir Fritz für immer im Gedächtnis."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Fritz unternommen?"},{"role":"user","content":"Mit Fritz ließ sich aus dem einfachsten Anlass ein schöner Tag machen. Ob bei einem Kaffee oder einem kleinen Ausflug, die Zeit verging immer wie im Flug. Daran erinnere ich mich besonders gern."},{"role":"assistant","content":"Wie hat Fritz Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"Fritz hat mich durch manche dunkle Stunde getragen. Mit Ruhe und Zuversicht wurde aus jedem Problem etwas Lösbares. Dafür bin ich für immer dankbar."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Fritz war?"},{"role":"user","content":"An eine Sache erinnern wir uns immer wieder mit einem Lächeln. Fritz brachte uns mit einer beiläufigen Bemerkung zum Lachen, ganz ohne Absicht. Genau das machte Fritz so liebenswert."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Fritz tragen Sie bis heute weiter?"},{"role":"user","content":"Eines hat mich besonders geprägt. Von Opa habe ich gelernt, dass sich Fleiß und Ausdauer immer auszahlen. Dafür bin ich für immer dankbar."},{"role":"assistant","content":"Wofür hat Fritz im Leben besonders gebrannt?"},{"role":"user","content":"Die Gartenarbeit war für Fritz weit mehr als nur ein Zeitvertreib. Mit viel Liebe zum Detail war Fritz stets bei der Sache. Daran denke ich besonders gern zurück."},{"role":"assistant","content":"Was werden Sie an Fritz am meisten vermissen?"},{"role":"user","content":"Ich vermisse die Gespräche mit Fritz mehr, als Worte sagen können. Es gab immer ein offenes Ohr und einen guten Rat. Diese Nähe wird mir für immer fehlen."},{"role":"assistant","content":"Was möchten Sie Fritz zum Abschied sagen?"},{"role":"user","content":"Lieber Fritz, der Abschied von dir fällt unendlich schwer. Was du mir gegeben hast, nehme ich für mein ganzes Leben mit. Bis wir uns eines Tages wiedersehen."}]'::jsonb)
on conflict (id) do update set
  memorial_id = excluded.memorial_id, contributor_name = excluded.contributor_name,
  relationship = excluded.relationship, contributor_gender = excluded.contributor_gender,
  messages = excluded.messages;

-- Werner Klein (Vereinskamerad)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAAAX', 'BAUER2', 'Werner Klein', 'Vereinskamerad', 'männlich', '[{"role":"assistant","content":"Wie haben Sie Fritz kennengelernt, und was hat Sie verbunden?"},{"role":"user","content":"Unsere Wege kreuzten sich vor langer Zeit, und Fritz wuchs mir schnell ans Herz. Als Vereinskamerad habe ich Fritz über viele Jahre erlebt. Eine bessere Begegnung hätte ich mir nicht wünschen können."},{"role":"assistant","content":"Gibt es eine Erinnerung an Fritz, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Eine Erinnerung ist mir besonders geblieben. Über dreißig Jahre saßen wir im Gesangverein im Bass direkt nebeneinander. Dieser Augenblick bedeutet mir bis heute sehr viel."},{"role":"assistant","content":"Welche Eigenschaften haben Fritz als Menschen besonders ausgemacht?"},{"role":"user","content":"Was Fritz als Mensch ausgemacht hat, lässt sich kaum in Worte fassen. Fritz war ein geselliger Kerl mit einem großen Herzen für seine Kameraden. Genau das werde ich an Fritz immer in Erinnerung behalten."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Fritz unternommen?"},{"role":"user","content":"Wir haben viele Unternehmungen miteinander geteilt, große wie kleine. Fritz war dabei stets mit Herz und voller Begeisterung bei der Sache. Solche Momente bleiben unvergesslich."},{"role":"assistant","content":"Wie hat Fritz Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"Gerade in Krisen zeigte sich, was in Fritz steckte. Da war immer ein offenes Ohr und eine helfende Hand. Diese Verlässlichkeit hat mir oft Kraft gegeben."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Fritz war?"},{"role":"user","content":"Mit Fritz wurde es nie langweilig, dafür war stets gesorgt. Eine kleine Anekdote nach der anderen begleitete unsere gemeinsamen Stunden. Diese Leichtigkeit werde ich besonders vermissen."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Fritz tragen Sie bis heute weiter?"},{"role":"user","content":"Von Fritz habe ich fürs Leben viel mitgenommen. Er zeigte mir, wie wichtig Zusammenhalt und Verlässlichkeit sind. An diesen Leitsatz halte ich mich bis heute."},{"role":"assistant","content":"Wofür hat Fritz im Leben besonders gebrannt?"},{"role":"user","content":"Die Leidenschaft von Fritz für das Singen im Gesangverein war wirklich ansteckend. Mit Hingabe und Ausdauer war Fritz immer dabei. Davon konnte sich jeder eine Scheibe abschneiden."},{"role":"assistant","content":"Was werden Sie an Fritz am meisten vermissen?"},{"role":"user","content":"Das Schwerste ist, dass Fritz nun nicht mehr da ist, wenn ich Rat suche. So oft möchte ich noch zum Hörer greifen. Dieser Verlust begleitet mich jeden Tag."},{"role":"assistant","content":"Was möchten Sie Fritz zum Abschied sagen?"},{"role":"user","content":"Lieber Fritz, danke, dass ich dich kennen und schätzen durfte. Deine Wärme und dein Vorbild werden mich immer begleiten. Schlaf gut und ruhe sanft."}]'::jsonb)
on conflict (id) do update set
  memorial_id = excluded.memorial_id, contributor_name = excluded.contributor_name,
  relationship = excluded.relationship, contributor_gender = excluded.contributor_gender,
  messages = excluded.messages;

-- Helmut Fischer (Arbeitskollege)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAAAY', 'BAUER2', 'Helmut Fischer', 'Arbeitskollege', 'männlich', '[{"role":"assistant","content":"Wie haben Sie Fritz kennengelernt, und was hat Sie verbunden?"},{"role":"user","content":"Ich lernte Fritz als Arbeitskollege kennen und schätzen. Vom ersten Moment an verstanden wir uns ohne viele Worte. Daraus erwuchs eine Verbindung, die mir bis heute viel bedeutet."},{"role":"assistant","content":"Gibt es eine Erinnerung an Fritz, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Wenn ich zurückdenke, taucht sofort ein bestimmtes Bild auf. Vierzig Jahre arbeiteten wir Seite an Seite, und auf Fritz war immer Verlass. Daran denke ich noch oft mit einem warmen Gefühl."},{"role":"assistant","content":"Welche Eigenschaften haben Fritz als Menschen besonders ausgemacht?"},{"role":"user","content":"Fritz hatte ein ganz besonderes Wesen. Fritz packte dort an, wo andere zögerten, und jammerte dabei nie. Diese Eigenschaften haben alle Menschen ringsum geprägt."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Fritz unternommen?"},{"role":"user","content":"Egal was wir zusammen taten, mit Fritz wurde es zu einer schönen Erinnerung. Gemeinsame Feiern und ruhige Nachmittage gehörten gleichermaßen dazu. Ich bin dankbar für jede dieser Stunden."},{"role":"assistant","content":"Wie hat Fritz Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"Auf Fritz war Verlass, wenn es darauf ankam. In schwierigen Momenten gab es Trost und Ermutigung statt leerer Worte. Das hat mir mehr bedeutet, als ich je sagen konnte."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Fritz war?"},{"role":"user","content":"Typisch Fritz war dieser ganz besondere Humor, der jede Runde auflockerte. Eine kleine Bemerkung reichte, und alle mussten lachen. Wenn ich daran denke, muss ich noch heute schmunzeln."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Fritz tragen Sie bis heute weiter?"},{"role":"user","content":"Fritz hat mir Werte vermittelt, die mich bis heute tragen. Von ihm lernte ich, dass ehrliche Arbeit ihren eigenen Stolz hat. Dieses Vermächtnis gebe ich gern weiter."},{"role":"assistant","content":"Wofür hat Fritz im Leben besonders gebrannt?"},{"role":"user","content":"Wenn es um das Skatspiel ging, blühte Fritz regelrecht auf. Diese Begeisterung hat viele Menschen im Umfeld angesteckt. Es war schön, Fritz dabei zu erleben."},{"role":"assistant","content":"Was werden Sie an Fritz am meisten vermissen?"},{"role":"user","content":"Mir fehlt die herzliche Art von Fritz, die jeden Raum wärmer machte. Gerade die kleinen Momente des Alltags vermisse ich am meisten. Es bleibt eine große Leere."},{"role":"assistant","content":"Was möchten Sie Fritz zum Abschied sagen?"},{"role":"user","content":"Lieber Fritz, du fehlst uns mehr, als sich in Worte fassen lässt. Wir werden dich in liebevoller Erinnerung behalten und oft von dir erzählen. Mach es gut, geliebter Mensch."}]'::jsonb)
on conflict (id) do update set
  memorial_id = excluded.memorial_id, contributor_name = excluded.contributor_name,
  relationship = excluded.relationship, contributor_gender = excluded.contributor_gender,
  messages = excluded.messages;

-- Gerda Klein (Freundin der Familie)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAAAZ', 'BAUER2', 'Gerda Klein', 'Freundin der Familie', 'weiblich', '[{"role":"assistant","content":"Wie haben Sie Fritz kennengelernt, und was hat Sie verbunden?"},{"role":"user","content":"Als Freundin der Familie war ich Fritz über die Jahre eng verbunden. Wir teilten Freud und Leid und konnten uns aufeinander verlassen. Solche Menschen trifft man im Leben nur selten."},{"role":"assistant","content":"Gibt es eine Erinnerung an Fritz, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Es gibt einen Moment, den ich nie vergessen werde. Bei jedem Grillfest war es Fritz, der mit seinen Geschichten für Stimmung sorgte. Solche Momente machen mich dankbar für die gemeinsame Zeit."},{"role":"assistant","content":"Welche Eigenschaften haben Fritz als Menschen besonders ausgemacht?"},{"role":"user","content":"Über den Charakter von Fritz könnte ich endlos erzählen. Fritz hatte einen trockenen Humor, der jeden sofort zum Lachen brachte. So bleibt mir Fritz für immer im Gedächtnis."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Fritz unternommen?"},{"role":"user","content":"Die gemeinsamen Unternehmungen mit Fritz habe ich immer genossen. Es war nie wichtig, was wir taten, sondern dass wir es zusammen taten. Diese Zeit war für mich ein echtes Geschenk."},{"role":"assistant","content":"Wie hat Fritz Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"In schweren Zeiten konnte ich mich immer auf Fritz verlassen. Ein gutes Wort oder einfach nur Zuhören kam stets im richtigen Moment. Diesen Rückhalt werde ich nie vergessen."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Fritz war?"},{"role":"user","content":"Es gab so viele kleine Geschichten, die einfach typisch Fritz waren. Selbst in den alltäglichsten Momenten steckte oft ein Augenzwinkern. Diese Heiterkeit fehlt mir sehr."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Fritz tragen Sie bis heute weiter?"},{"role":"user","content":"Eines hat mich besonders geprägt. Er zeigte mir, dass man das Leben trotz aller Sorgen leicht nehmen darf. Dafür bin ich für immer dankbar."},{"role":"assistant","content":"Wofür hat Fritz im Leben besonders gebrannt?"},{"role":"user","content":"Fritz liebte das Heimwerken über alles. Man spürte sofort, wie viel Freude das bereitete. Diese Hingabe hat mich immer beeindruckt."},{"role":"assistant","content":"Was werden Sie an Fritz am meisten vermissen?"},{"role":"user","content":"Am meisten werde ich die Gegenwart von Fritz vermissen, dieses Gefühl von Geborgenheit. Schon eine kurze Begegnung konnte den ganzen Tag heller machen. Diese Lücke lässt sich nicht füllen."},{"role":"assistant","content":"Was möchten Sie Fritz zum Abschied sagen?"},{"role":"user","content":"Lieber Fritz, dein Andenken bleibt für immer lebendig. Ich bin dankbar für jeden Augenblick, den wir teilen durften. In Liebe und Dankbarkeit nehme ich Abschied."}]'::jsonb)
on conflict (id) do update set
  memorial_id = excluded.memorial_id, contributor_name = excluded.contributor_name,
  relationship = excluded.relationship, contributor_gender = excluded.contributor_gender,
  messages = excluded.messages;

-- Rudolf Bauer (Bruder)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAAA2', 'BAUER2', 'Rudolf Bauer', 'Bruder', 'männlich', '[{"role":"assistant","content":"Wie würden Sie Ihre Beziehung zu Fritz als Bruder beschreiben?"},{"role":"user","content":"Schon als Kind spürte ich, wie besonders meine Verbindung zu Fritz war. Als Bruder durfte ich Fritz über viele Jahre begleiten. Das habe ich nie als selbstverständlich genommen."},{"role":"assistant","content":"Gibt es eine Erinnerung an Fritz, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Eine Erinnerung ist mir besonders geblieben. Als Jungen streiften wir gemeinsam durch die Wälder und bauten uns geheime Verstecke. Dieser Augenblick bedeutet mir bis heute sehr viel."},{"role":"assistant","content":"Welche Eigenschaften haben Fritz als Menschen besonders ausgemacht?"},{"role":"user","content":"Was Fritz als Mensch ausgemacht hat, lässt sich kaum in Worte fassen. Mein Bruder war der Fels, auf den sich die ganze Familie verlassen konnte. Genau das werde ich an Fritz immer in Erinnerung behalten."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Fritz unternommen?"},{"role":"user","content":"Am liebsten haben wir gemeinsam Zeit in Ruhe verbracht, ganz ohne großes Programm. Schon ein Spaziergang oder ein langes Gespräch mit Fritz war etwas Besonderes. Diese gemeinsamen Stunden fehlen mir heute am meisten."},{"role":"assistant","content":"Wie hat Fritz Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"Wenn es mir einmal nicht gut ging, war Fritz sofort zur Stelle. Ohne viel Aufhebens wurde geholfen, ganz selbstverständlich. So einen Menschen an seiner Seite zu wissen, war ein großes Glück."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Fritz war?"},{"role":"user","content":"Fritz hatte ein Talent dafür, im richtigen Moment das Richtige zu sagen. Manche Bemerkung sorgt in der Familie bis heute für Gelächter. Solche Geschichten halten die Erinnerung lebendig."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Fritz tragen Sie bis heute weiter?"},{"role":"user","content":"Von Fritz habe ich fürs Leben viel mitgenommen. Von ihm lernte ich, dass man als Familie immer zusammenhält. An diesen Leitsatz halte ich mich bis heute."},{"role":"assistant","content":"Wofür hat Fritz im Leben besonders gebrannt?"},{"role":"user","content":"Für das Angeln konnte Fritz sich jederzeit begeistern. Stundenlang ging Fritz darin auf und vergaß die Zeit. Das gehörte einfach zu Fritz."},{"role":"assistant","content":"Was werden Sie an Fritz am meisten vermissen?"},{"role":"user","content":"Was mir am meisten fehlt, ist die Stimme von Fritz und das vertraute Lachen. So viele kleine Gewohnheiten erinnern mich täglich daran. Der Abschied tut sehr weh."},{"role":"assistant","content":"Was möchten Sie Fritz zum Abschied sagen?"},{"role":"user","content":"Lieber Fritz, ich danke dir von Herzen für all die gemeinsamen Jahre. Du wirst für immer einen festen Platz in meinem Herzen behalten. Ruhe nun in Frieden."}]'::jsonb)
on conflict (id) do update set
  memorial_id = excluded.memorial_id, contributor_name = excluded.contributor_name,
