insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAAA5', 'BAUER2', 'Stefan Bauer', 'Enkel', 'männlich', '[{"role":"assistant","content":"Wie würden Sie Ihre Beziehung zu Fritz als Enkel beschreiben?"},{"role":"user","content":"Unsere Beziehung war von tiefem Vertrauen geprägt. Als Enkel konnte ich mit Fritz über alles reden, im Guten wie im Schweren. Dafür bin ich unendlich dankbar."},{"role":"assistant","content":"Gibt es eine Erinnerung an Fritz, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Eine Erinnerung ist mir besonders geblieben. Opa brachte mir bei, wie man einen Nagel gerade einschlägt und ein Fahrrad repariert. Dieser Augenblick bedeutet mir bis heute sehr viel."},{"role":"assistant","content":"Welche Eigenschaften haben Fritz als Menschen besonders ausgemacht?"},{"role":"user","content":"Was Fritz als Mensch ausgemacht hat, lässt sich kaum in Worte fassen. Opa hatte für jede Lebenslage einen klugen Rat parat. Genau das werde ich an Fritz immer in Erinnerung behalten."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Fritz unternommen?"},{"role":"user","content":"Egal was wir zusammen taten, mit Fritz wurde es zu einer schönen Erinnerung. Gemeinsame Feiern und ruhige Nachmittage gehörten gleichermaßen dazu. Ich bin dankbar für jede dieser Stunden."},{"role":"assistant","content":"Wie hat Fritz Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"Auf Fritz war Verlass, wenn es darauf ankam. In schwierigen Momenten gab es Trost und Ermutigung statt leerer Worte. Das hat mir mehr bedeutet, als ich je sagen konnte."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Fritz war?"},{"role":"user","content":"Typisch Fritz war dieser ganz besondere Humor, der jede Runde auflockerte. Eine kleine Bemerkung reichte, und alle mussten lachen. Wenn ich daran denke, muss ich noch heute schmunzeln."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Fritz tragen Sie bis heute weiter?"},{"role":"user","content":"Von Fritz habe ich fürs Leben viel mitgenommen. Er lehrte mich, dass man mit den eigenen Händen viel erschaffen kann. An diesen Leitsatz halte ich mich bis heute."},{"role":"assistant","content":"Wofür hat Fritz im Leben besonders gebrannt?"},{"role":"user","content":"Wenn es um das Skatspiel ging, blühte Fritz regelrecht auf. Diese Begeisterung hat viele Menschen im Umfeld angesteckt. Es war schön, Fritz dabei zu erleben."},{"role":"assistant","content":"Was werden Sie an Fritz am meisten vermissen?"},{"role":"user","content":"Mir fehlt die herzliche Art von Fritz, die jeden Raum wärmer machte. Gerade die kleinen Momente des Alltags vermisse ich am meisten. Es bleibt eine große Leere."},{"role":"assistant","content":"Was möchten Sie Fritz zum Abschied sagen?"},{"role":"user","content":"Lieber Fritz, du fehlst uns mehr, als sich in Worte fassen lässt. Wir werden dich in liebevoller Erinnerung behalten und oft von dir erzählen. Mach es gut, geliebter Mensch."}]'::jsonb)
on conflict (id) do update set
  memorial_id = excluded.memorial_id, contributor_name = excluded.contributor_name,
  relationship = excluded.relationship, contributor_gender = excluded.contributor_gender,
  messages = excluded.messages;

-- Manfred Lehmann (Chorkamerad)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAAA6', 'BAUER2', 'Manfred Lehmann', 'Chorkamerad', 'männlich', '[{"role":"assistant","content":"Wie haben Sie Fritz kennengelernt, und was hat Sie verbunden?"},{"role":"user","content":"Als Chorkamerad war ich Fritz über die Jahre eng verbunden. Wir teilten Freud und Leid und konnten uns aufeinander verlassen. Solche Menschen trifft man im Leben nur selten."},{"role":"assistant","content":"Gibt es eine Erinnerung an Fritz, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Wenn ich zurückdenke, taucht sofort ein bestimmtes Bild auf. Bei den Sommerfesten stimmte Fritz aus dem Stegreif ein Lied nach dem anderen an. Daran denke ich noch oft mit einem warmen Gefühl."},{"role":"assistant","content":"Welche Eigenschaften haben Fritz als Menschen besonders ausgemacht?"},{"role":"user","content":"Fritz hatte ein ganz besonderes Wesen. Fritz war die Seele unseres Chores und riss alle mit. Diese Eigenschaften haben alle Menschen ringsum geprägt."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Fritz unternommen?"},{"role":"user","content":"Die gemeinsamen Unternehmungen mit Fritz habe ich immer genossen. Es war nie wichtig, was wir taten, sondern dass wir es zusammen taten. Diese Zeit war für mich ein echtes Geschenk."},{"role":"assistant","content":"Wie hat Fritz Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"In schweren Zeiten konnte ich mich immer auf Fritz verlassen. Ein gutes Wort oder einfach nur Zuhören kam stets im richtigen Moment. Diesen Rückhalt werde ich nie vergessen."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Fritz war?"},{"role":"user","content":"Es gab so viele kleine Geschichten, die einfach typisch Fritz waren. Selbst in den alltäglichsten Momenten steckte oft ein Augenzwinkern. Diese Heiterkeit fehlt mir sehr."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Fritz tragen Sie bis heute weiter?"},{"role":"user","content":"Fritz hat mir Werte vermittelt, die mich bis heute tragen. Von ihm lernte ich, dass Musik Menschen verbindet wie kaum etwas anderes. Dieses Vermächtnis gebe ich gern weiter."},{"role":"assistant","content":"Wofür hat Fritz im Leben besonders gebrannt?"},{"role":"user","content":"Fritz liebte das Heimwerken über alles. Man spürte sofort, wie viel Freude das bereitete. Diese Hingabe hat mich immer beeindruckt."},{"role":"assistant","content":"Was werden Sie an Fritz am meisten vermissen?"},{"role":"user","content":"Am meisten werde ich die Gegenwart von Fritz vermissen, dieses Gefühl von Geborgenheit. Schon eine kurze Begegnung konnte den ganzen Tag heller machen. Diese Lücke lässt sich nicht füllen."},{"role":"assistant","content":"Was möchten Sie Fritz zum Abschied sagen?"},{"role":"user","content":"Lieber Fritz, dein Andenken bleibt für immer lebendig. Ich bin dankbar für jeden Augenblick, den wir teilen durften. In Liebe und Dankbarkeit nehme ich Abschied."}]'::jsonb)
on conflict (id) do update set
  memorial_id = excluded.memorial_id, contributor_name = excluded.contributor_name,
  relationship = excluded.relationship, contributor_gender = excluded.contributor_gender,
  messages = excluded.messages;

-- Ursula Bauer (Schwägerin)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAAA7', 'BAUER2', 'Ursula Bauer', 'Schwägerin', 'weiblich', '[{"role":"assistant","content":"Wie würden Sie Ihre Beziehung zu Fritz als Schwägerin beschreiben?"},{"role":"user","content":"Schon als Kind spürte ich, wie besonders meine Verbindung zu Fritz war. Als Schwägerin durfte ich Fritz über viele Jahre begleiten. Das habe ich nie als selbstverständlich genommen."},{"role":"assistant","content":"Gibt es eine Erinnerung an Fritz, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Es gibt einen Moment, den ich nie vergessen werde. An keinem Festtag fehlte Fritz mit einem Witz und einem guten Glas in der Hand. Solche Momente machen mich dankbar für die gemeinsame Zeit."},{"role":"assistant","content":"Welche Eigenschaften haben Fritz als Menschen besonders ausgemacht?"},{"role":"user","content":"Über den Charakter von Fritz könnte ich endlos erzählen. Fritz nahm jeden in der Familie genau so an, wie er war. So bleibt mir Fritz für immer im Gedächtnis."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Fritz unternommen?"},{"role":"user","content":"Am liebsten haben wir gemeinsam Zeit in Ruhe verbracht, ganz ohne großes Programm. Schon ein Spaziergang oder ein langes Gespräch mit Fritz war etwas Besonderes. Diese gemeinsamen Stunden fehlen mir heute am meisten."},{"role":"assistant","content":"Wie hat Fritz Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"Wenn es mir einmal nicht gut ging, war Fritz sofort zur Stelle. Ohne viel Aufhebens wurde geholfen, ganz selbstverständlich. So einen Menschen an seiner Seite zu wissen, war ein großes Glück."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Fritz war?"},{"role":"user","content":"Fritz hatte ein Talent dafür, im richtigen Moment das Richtige zu sagen. Manche Bemerkung sorgt in der Familie bis heute für Gelächter. Solche Geschichten halten die Erinnerung lebendig."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Fritz tragen Sie bis heute weiter?"},{"role":"user","content":"Eines hat mich besonders geprägt. Er zeigte mir, dass ein offenes Haus und ein offenes Herz zusammengehören. Dafür bin ich für immer dankbar."},{"role":"assistant","content":"Wofür hat Fritz im Leben besonders gebrannt?"},{"role":"user","content":"Für das Angeln konnte Fritz sich jederzeit begeistern. Stundenlang ging Fritz darin auf und vergaß die Zeit. Das gehörte einfach zu Fritz."},{"role":"assistant","content":"Was werden Sie an Fritz am meisten vermissen?"},{"role":"user","content":"Was mir am meisten fehlt, ist die Stimme von Fritz und das vertraute Lachen. So viele kleine Gewohnheiten erinnern mich täglich daran. Der Abschied tut sehr weh."},{"role":"assistant","content":"Was möchten Sie Fritz zum Abschied sagen?"},{"role":"user","content":"Lieber Fritz, ich danke dir von Herzen für all die gemeinsamen Jahre. Du wirst für immer einen festen Platz in meinem Herzen behalten. Ruhe nun in Frieden."}]'::jsonb)
on conflict (id) do update set
