-- Klaus Wagner (Ehemann)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAAA8', 'WAGNER', 'Klaus Wagner', 'Ehemann', 'männlich', '[{"role":"assistant","content":"Wie würden Sie Ihre Beziehung zu Elisabeth als Ehemann beschreiben?"},{"role":"user","content":"Als Ehemann stand ich Elisabeth mein Leben lang besonders nahe. Wir haben unzählige Stunden miteinander verbracht und vieles gemeinsam durchlebt. Diese enge Verbindung hat mich zu dem Menschen gemacht, der ich heute bin."},{"role":"assistant","content":"Gibt es eine Erinnerung an Elisabeth, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Eine Erinnerung ist mir besonders geblieben. In der Bibliothek lieh sie sich ein Buch von mir aus und gab mir dafür ihr Herz. Dieser Augenblick bedeutet mir bis heute sehr viel."},{"role":"assistant","content":"Welche Eigenschaften haben Elisabeth als Menschen besonders ausgemacht?"},{"role":"user","content":"Was Elisabeth als Mensch ausgemacht hat, lässt sich kaum in Worte fassen. Meine Frau war klug, warmherzig und voller Lebensfreude. Genau das werde ich an Elisabeth immer in Erinnerung behalten."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Elisabeth unternommen?"},{"role":"user","content":"Mit Elisabeth ließ sich aus dem einfachsten Anlass ein schöner Tag machen. Ob bei einem Kaffee oder einem kleinen Ausflug, die Zeit verging immer wie im Flug. Daran erinnere ich mich besonders gern."},{"role":"assistant","content":"Wie hat Elisabeth Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"Elisabeth hat mich durch manche dunkle Stunde getragen. Mit Ruhe und Zuversicht wurde aus jedem Problem etwas Lösbares. Dafür bin ich für immer dankbar."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Elisabeth war?"},{"role":"user","content":"An eine Sache erinnern wir uns immer wieder mit einem Lächeln. Elisabeth brachte uns mit einer beiläufigen Bemerkung zum Lachen, ganz ohne Absicht. Genau das machte Elisabeth so liebenswert."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Elisabeth tragen Sie bis heute weiter?"},{"role":"user","content":"Von Elisabeth habe ich fürs Leben viel mitgenommen. Elisabeth lehrte mich, offen zu reden und nie mit Groll schlafen zu gehen. An diesen Leitsatz halte ich mich bis heute."},{"role":"assistant","content":"Wofür hat Elisabeth im Leben besonders gebrannt?"},{"role":"user","content":"Das Lesen war für Elisabeth weit mehr als nur ein Zeitvertreib. Mit viel Liebe zum Detail war Elisabeth stets bei der Sache. Daran denke ich besonders gern zurück."},{"role":"assistant","content":"Was werden Sie an Elisabeth am meisten vermissen?"},{"role":"user","content":"Ich vermisse die Gespräche mit Elisabeth mehr, als Worte sagen können. Es gab immer ein offenes Ohr und einen guten Rat. Diese Nähe wird mir für immer fehlen."},{"role":"assistant","content":"Was möchten Sie Elisabeth zum Abschied sagen?"},{"role":"user","content":"Liebe Elisabeth, der Abschied von dir fällt unendlich schwer. Was du mir gegeben hast, nehme ich für mein ganzes Leben mit. Bis wir uns eines Tages wiedersehen."}]'::jsonb)
on conflict (id) do update set
  memorial_id = excluded.memorial_id, contributor_name = excluded.contributor_name,
  relationship = excluded.relationship, contributor_gender = excluded.contributor_gender,
  messages = excluded.messages;

-- Julia Wagner (Tochter)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAAA9', 'WAGNER', 'Julia Wagner', 'Tochter', 'weiblich', '[{"role":"assistant","content":"Wie würden Sie Ihre Beziehung zu Elisabeth als Tochter beschreiben?"},{"role":"user","content":"Elisabeth war für mich weit mehr als nur Familie. Als Tochter habe ich früh gelernt, wie viel Halt eine solche Beziehung geben kann. Auf Elisabeth war einfach immer Verlass."},{"role":"assistant","content":"Gibt es eine Erinnerung an Elisabeth, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Wenn ich zurückdenke, taucht sofort ein bestimmtes Bild auf. Jeden Abend las sie mir vor und gab dabei jeder Figur eine eigene Stimme. Daran denke ich noch oft mit einem warmen Gefühl."},{"role":"assistant","content":"Welche Eigenschaften haben Elisabeth als Menschen besonders ausgemacht?"},{"role":"user","content":"Elisabeth hatte ein ganz besonderes Wesen. Meine Mutter war stark und liebevoll zugleich und immer meine erste Anlaufstelle. Diese Eigenschaften haben alle Menschen ringsum geprägt."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Elisabeth unternommen?"},{"role":"user","content":"Wir haben viele Unternehmungen miteinander geteilt, große wie kleine. Elisabeth war dabei stets mit Herz und voller Begeisterung bei der Sache. Solche Momente bleiben unvergesslich."},{"role":"assistant","content":"Wie hat Elisabeth Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"Gerade in Krisen zeigte sich, was in Elisabeth steckte. Da war immer ein offenes Ohr und eine helfende Hand. Diese Verlässlichkeit hat mir oft Kraft gegeben."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Elisabeth war?"},{"role":"user","content":"Mit Elisabeth wurde es nie langweilig, dafür war stets gesorgt. Eine kleine Anekdote nach der anderen begleitete unsere gemeinsamen Stunden. Diese Leichtigkeit werde ich besonders vermissen."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Elisabeth tragen Sie bis heute weiter?"},{"role":"user","content":"Elisabeth hat mir Werte vermittelt, die mich bis heute tragen. Sie lehrte mich, stets für meine Überzeugungen einzustehen. Dieses Vermächtnis gebe ich gern weiter."},{"role":"assistant","content":"Wofür hat Elisabeth im Leben besonders gebrannt?"},{"role":"user","content":"Die Leidenschaft von Elisabeth für das Reisen war wirklich ansteckend. Mit Hingabe und Ausdauer war Elisabeth immer dabei. Davon konnte sich jeder eine Scheibe abschneiden."},{"role":"assistant","content":"Was werden Sie an Elisabeth am meisten vermissen?"},{"role":"user","content":"Das Schwerste ist, dass Elisabeth nun nicht mehr da ist, wenn ich Rat suche. So oft möchte ich noch zum Hörer greifen. Dieser Verlust begleitet mich jeden Tag."},{"role":"assistant","content":"Was möchten Sie Elisabeth zum Abschied sagen?"},{"role":"user","content":"Liebe Elisabeth, danke, dass ich dich kennen und schätzen durfte. Deine Wärme und dein Vorbild werden mich immer begleiten. Schlaf gut und ruhe sanft."}]'::jsonb)
