-- Wolfgang Maier (Schwager)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAABK', 'WAGNER', 'Wolfgang Maier', 'Schwager', 'männlich', '[{"role":"assistant","content":"Wie würden Sie Ihre Beziehung zu Elisabeth als Schwager beschreiben?"},{"role":"user","content":"Elisabeth war für mich weit mehr als nur Familie. Als Schwager habe ich früh gelernt, wie viel Halt eine solche Beziehung geben kann. Auf Elisabeth war einfach immer Verlass."},{"role":"assistant","content":"Gibt es eine Erinnerung an Elisabeth, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Es gibt einen Moment, den ich nie vergessen werde. Bei Familienfeiern entfachte Elisabeth stets die spannendsten Gespräche am Tisch. Solche Momente machen mich dankbar für die gemeinsame Zeit."},{"role":"assistant","content":"Welche Eigenschaften haben Elisabeth als Menschen besonders ausgemacht?"},{"role":"user","content":"Über den Charakter von Elisabeth könnte ich endlos erzählen. Elisabeth hatte einen wachen Verstand und ein noch wärmeres Herz. So bleibt mir Elisabeth für immer im Gedächtnis."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Elisabeth unternommen?"},{"role":"user","content":"Wir haben viele Unternehmungen miteinander geteilt, große wie kleine. Elisabeth war dabei stets mit Herz und voller Begeisterung bei der Sache. Solche Momente bleiben unvergesslich."},{"role":"assistant","content":"Wie hat Elisabeth Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"Gerade in Krisen zeigte sich, was in Elisabeth steckte. Da war immer ein offenes Ohr und eine helfende Hand. Diese Verlässlichkeit hat mir oft Kraft gegeben."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Elisabeth war?"},{"role":"user","content":"Mit Elisabeth wurde es nie langweilig, dafür war stets gesorgt. Eine kleine Anekdote nach der anderen begleitete unsere gemeinsamen Stunden. Diese Leichtigkeit werde ich besonders vermissen."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Elisabeth tragen Sie bis heute weiter?"},{"role":"user","content":"Eines hat mich besonders geprägt. Von ihr lernte ich, andere Meinungen zu achten und neugierig zu bleiben. Dafür bin ich für immer dankbar."},{"role":"assistant","content":"Wofür hat Elisabeth im Leben besonders gebrannt?"},{"role":"user","content":"Die Leidenschaft von Elisabeth für das Reisen war wirklich ansteckend. Mit Hingabe und Ausdauer war Elisabeth immer dabei. Davon konnte sich jeder eine Scheibe abschneiden."},{"role":"assistant","content":"Was werden Sie an Elisabeth am meisten vermissen?"},{"role":"user","content":"Das Schwerste ist, dass Elisabeth nun nicht mehr da ist, wenn ich Rat suche. So oft möchte ich noch zum Hörer greifen. Dieser Verlust begleitet mich jeden Tag."},{"role":"assistant","content":"Was möchten Sie Elisabeth zum Abschied sagen?"},{"role":"user","content":"Liebe Elisabeth, danke, dass ich dich kennen und schätzen durfte. Deine Wärme und dein Vorbild werden mich immer begleiten. Schlaf gut und ruhe sanft."}]'::jsonb)
on conflict (id) do update set
  memorial_id = excluded.memorial_id, contributor_name = excluded.contributor_name,
  relationship = excluded.relationship, contributor_gender = excluded.contributor_gender,
  messages = excluded.messages;

-- Emma Becker (Enkelin)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAABL', 'WAGNER', 'Emma Becker', 'Enkelin', 'weiblich', '[{"role":"assistant","content":"Wie würden Sie Ihre Beziehung zu Elisabeth als Enkelin beschreiben?"},{"role":"user","content":"Unsere Beziehung war von tiefem Vertrauen geprägt. Als Enkelin konnte ich mit Elisabeth über alles reden, im Guten wie im Schweren. Dafür bin ich unendlich dankbar."},{"role":"assistant","content":"Gibt es eine Erinnerung an Elisabeth, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Eine Erinnerung ist mir besonders geblieben. Oma schenkte mir mein erstes Tagebuch und sagte, ich solle meine Gedanken festhalten. Dieser Augenblick bedeutet mir bis heute sehr viel."},{"role":"assistant","content":"Welche Eigenschaften haben Elisabeth als Menschen besonders ausgemacht?"},{"role":"user","content":"Was Elisabeth als Mensch ausgemacht hat, lässt sich kaum in Worte fassen. Oma nahm sich für jede meiner tausend Fragen geduldig Zeit. Genau das werde ich an Elisabeth immer in Erinnerung behalten."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Elisabeth unternommen?"},{"role":"user","content":"Egal was wir zusammen taten, mit Elisabeth wurde es zu einer schönen Erinnerung. Gemeinsame Feiern und ruhige Nachmittage gehörten gleichermaßen dazu. Ich bin dankbar für jede dieser Stunden."},{"role":"assistant","content":"Wie hat Elisabeth Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"Auf Elisabeth war Verlass, wenn es darauf ankam. In schwierigen Momenten gab es Trost und Ermutigung statt leerer Worte. Das hat mir mehr bedeutet, als ich je sagen konnte."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Elisabeth war?"},{"role":"user","content":"Typisch Elisabeth war dieser ganz besondere Humor, der jede Runde auflockerte. Eine kleine Bemerkung reichte, und alle mussten lachen. Wenn ich daran denke, muss ich noch heute schmunzeln."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Elisabeth tragen Sie bis heute weiter?"},{"role":"user","content":"Von Elisabeth habe ich fürs Leben viel mitgenommen. Sie lehrte mich, an mich selbst zu glauben und mutig zu sein. An diesen Leitsatz halte ich mich bis heute."},{"role":"assistant","content":"Wofür hat Elisabeth im Leben besonders gebrannt?"},{"role":"user","content":"Wenn es um das Klavierspiel ging, blühte Elisabeth regelrecht auf. Diese Begeisterung hat viele Menschen im Umfeld angesteckt. Es war schön, Elisabeth dabei zu erleben."},{"role":"assistant","content":"Was werden Sie an Elisabeth am meisten vermissen?"},{"role":"user","content":"Mir fehlt die herzliche Art von Elisabeth, die jeden Raum wärmer machte. Gerade die kleinen Momente des Alltags vermisse ich am meisten. Es bleibt eine große Leere."},{"role":"assistant","content":"Was möchten Sie Elisabeth zum Abschied sagen?"},{"role":"user","content":"Liebe Elisabeth, du fehlst uns mehr, als sich in Worte fassen lässt. Wir werden dich in liebevoller Erinnerung behalten und oft von dir erzählen. Mach es gut, geliebter Mensch."}]'::jsonb)
on conflict (id) do update set
  memorial_id = excluded.memorial_id, contributor_name = excluded.contributor_name,
  relationship = excluded.relationship, contributor_gender = excluded.contributor_gender,
  messages = excluded.messages;

-- Katharina Wagner (Nichte)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAABM', 'WAGNER', 'Katharina Wagner', 'Nichte', 'weiblich', '[{"role":"assistant","content":"Wie würden Sie Ihre Beziehung zu Elisabeth als Nichte beschreiben?"},{"role":"user","content":"Ich hatte das große Glück, Elisabeth als Nichte so nah zu sein. Gemeinsame Feste, Sorgen und Freuden haben uns über die Jahre fest verbunden. Diese Nähe werde ich für immer in meinem Herzen tragen."},{"role":"assistant","content":"Gibt es eine Erinnerung an Elisabeth, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Wenn ich zurückdenke, taucht sofort ein bestimmtes Bild auf. In den Sommerferien durfte ich bei ihr wohnen, und sie zeigte mir ihre Lieblingsgedichte. Daran denke ich noch oft mit einem warmen Gefühl."},{"role":"assistant","content":"Welche Eigenschaften haben Elisabeth als Menschen besonders ausgemacht?"},{"role":"user","content":"Elisabeth hatte ein ganz besonderes Wesen. Meine Tante Elisabeth war eine Frau voller Anmut und Klugheit. Diese Eigenschaften haben alle Menschen ringsum geprägt."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Elisabeth unternommen?"},{"role":"user","content":"Die gemeinsamen Unternehmungen mit Elisabeth habe ich immer genossen. Es war nie wichtig, was wir taten, sondern dass wir es zusammen taten. Diese Zeit war für mich ein echtes Geschenk."},{"role":"assistant","content":"Wie hat Elisabeth Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"In schweren Zeiten konnte ich mich immer auf Elisabeth verlassen. Ein gutes Wort oder einfach nur Zuhören kam stets im richtigen Moment. Diesen Rückhalt werde ich nie vergessen."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Elisabeth war?"},{"role":"user","content":"Es gab so viele kleine Geschichten, die einfach typisch Elisabeth waren. Selbst in den alltäglichsten Momenten steckte oft ein Augenzwinkern. Diese Heiterkeit fehlt mir sehr."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Elisabeth tragen Sie bis heute weiter?"},{"role":"user","content":"Elisabeth hat mir Werte vermittelt, die mich bis heute tragen. Von ihr lernte ich, dass Sprache und Worte eine ganz eigene Magie haben. Dieses Vermächtnis gebe ich gern weiter."},{"role":"assistant","content":"Wofür hat Elisabeth im Leben besonders gebrannt?"},{"role":"user","content":"Elisabeth liebte das Wandern über alles. Man spürte sofort, wie viel Freude das bereitete. Diese Hingabe hat mich immer beeindruckt."},{"role":"assistant","content":"Was werden Sie an Elisabeth am meisten vermissen?"},{"role":"user","content":"Am meisten werde ich die Gegenwart von Elisabeth vermissen, dieses Gefühl von Geborgenheit. Schon eine kurze Begegnung konnte den ganzen Tag heller machen. Diese Lücke lässt sich nicht füllen."},{"role":"assistant","content":"Was möchten Sie Elisabeth zum Abschied sagen?"},{"role":"user","content":"Liebe Elisabeth, dein Andenken bleibt für immer lebendig. Ich bin dankbar für jeden Augenblick, den wir teilen durften. In Liebe und Dankbarkeit nehme ich Abschied."}]'::jsonb)
on conflict (id) do update set
  memorial_id = excluded.memorial_id, contributor_name = excluded.contributor_name,
  relationship = excluded.relationship, contributor_gender = excluded.contributor_gender,
  messages = excluded.messages;

-- Friedrich Köhler (Kollege)
insert into contributions
  (id, memorial_id, contributor_name, relationship, contributor_gender, messages)
values ('CTAABN', 'WAGNER', 'Friedrich Köhler', 'Kollege', 'männlich', '[{"role":"assistant","content":"Wie haben Sie Elisabeth kennengelernt, und was hat Sie verbunden?"},{"role":"user","content":"Elisabeth kennenzulernen gehört zu den schönen Fügungen meines Lebens. Als Kollege habe ich Elisabeth oft erlebt und immer mehr geschätzt. Diese Verbundenheit werde ich in Ehren halten."},{"role":"assistant","content":"Gibt es eine Erinnerung an Elisabeth, die Ihnen sofort in den Sinn kommt?"},{"role":"user","content":"Es gibt einen Moment, den ich nie vergessen werde. Als junger Lehrer nahm Elisabeth mich unter ihre Fittiche und teilte all ihr Wissen. Solche Momente machen mich dankbar für die gemeinsame Zeit."},{"role":"assistant","content":"Welche Eigenschaften haben Elisabeth als Menschen besonders ausgemacht?"},{"role":"user","content":"Über den Charakter von Elisabeth könnte ich endlos erzählen. Elisabeth war eine geschätzte Kollegin, zu der alle aufsahen. So bleibt mir Elisabeth für immer im Gedächtnis."},{"role":"assistant","content":"Was haben Sie am liebsten gemeinsam mit Elisabeth unternommen?"},{"role":"user","content":"Am liebsten haben wir gemeinsam Zeit in Ruhe verbracht, ganz ohne großes Programm. Schon ein Spaziergang oder ein langes Gespräch mit Elisabeth war etwas Besonderes. Diese gemeinsamen Stunden fehlen mir heute am meisten."},{"role":"assistant","content":"Wie hat Elisabeth Ihnen in schwierigen Zeiten zur Seite gestanden?"},{"role":"user","content":"Wenn es mir einmal nicht gut ging, war Elisabeth sofort zur Stelle. Ohne viel Aufhebens wurde geholfen, ganz selbstverständlich. So einen Menschen an seiner Seite zu wissen, war ein großes Glück."},{"role":"assistant","content":"Gibt es eine Geschichte oder Begebenheit, die typisch für Elisabeth war?"},{"role":"user","content":"Elisabeth hatte ein Talent dafür, im richtigen Moment das Richtige zu sagen. Manche Bemerkung sorgt in der Familie bis heute für Gelächter. Solche Geschichten halten die Erinnerung lebendig."},{"role":"assistant","content":"Welche Werte oder welche Weisheit von Elisabeth tragen Sie bis heute weiter?"},{"role":"user","content":"Eines hat mich besonders geprägt. Sie zeigte mir, dass man mit Geduld und Herz zum besten Lehrer wird. Dafür bin ich für immer dankbar."},{"role":"assistant","content":"Wofür hat Elisabeth im Leben besonders gebrannt?"},{"role":"user","content":"Für das Erlernen neuer Sprachen konnte Elisabeth sich jederzeit begeistern. Stundenlang ging Elisabeth darin auf und vergaß die Zeit. Das gehörte einfach zu Elisabeth."},{"role":"assistant","content":"Was werden Sie an Elisabeth am meisten vermissen?"},{"role":"user","content":"Was mir am meisten fehlt, ist die Stimme von Elisabeth und das vertraute Lachen. So viele kleine Gewohnheiten erinnern mich täglich daran. Der Abschied tut sehr weh."},{"role":"assistant","content":"Was möchten Sie Elisabeth zum Abschied sagen?"},{"role":"user","content":"Liebe Elisabeth, ich danke dir von Herzen für all die gemeinsamen Jahre. Du wirst für immer einen festen Platz in meinem Herzen behalten. Ruhe nun in Frieden."}]'::jsonb)
